let peopleMode='learn',profileIndex=0,peopleQuestionIndex=0;
function escapeHTML(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function peopleAnswerMatches(value,question){return question.answers.some(a=>normalize(value)===normalize(a))}
function profileHTML(p){return `<aside class="person-card"><span class="eyebrow">虚构人物 · DATOS PERSONALES</span><h2 lang="es">${p.name} ${p.paternal} ${p.maternal}</h2><dl><dt>名字 · Nombre</dt><dd>${p.name}</dd><dt>父姓 · Apellido paterno</dt><dd>${p.paternal}</dd><dt>母姓 · Apellido materno</dt><dd>${p.maternal}</dd><dt>年龄 · Edad</dt><dd>${p.age} 岁</dd><dt>国家 · País</dt><dd>${p.country}</dd><dt>国籍 · Nacionalidad</dt><dd>${p.nationality}</dd><dt>居住地 · Residencia</dt><dd>${p.city}</dd><dt>爱好 · Aficiones</dt><dd>${p.hobby}</dd></dl><p>年龄以 2026 年 10 月 13 日为准。练习时扮演卡片人物，无需填写自己的真实信息。</p></aside>`}
function renderPeople(){const p=peopleProfiles[profileIndex],third=peopleMode==='others',questions=peopleQuestions(p,third),q=questions[peopleQuestionIndex];
 app.innerHTML=`<a href="#" class="back">← 所有主题</a><div class="page-head"><div><div class="topic-number">主题 02 · DATOS PERSONALES</div><h1>认识你和我</h1><p>第 4–6 周 · 听问题、介绍自己，也介绍别人。</p></div><div class="tabs" role="group" aria-label="个人信息练习模式">${[['learn','听读句型'],['self','介绍自己'],['others','介绍别人']].map(([v,l])=>`<button data-people-mode="${v}" class="${peopleMode===v?'active':''}" aria-pressed="${peopleMode===v}">${l}</button>`).join('')}</div></div><section class="workspace"><div class="toolbar"><div><h3>${peopleMode==='learn'?'先听一听，熟悉问与答':third?'看资料，介绍这位朋友':'你就是卡片中的人物'}</h3><p>姓名、姓氏、年龄、国家、居住地和爱好。</p></div><div class="range" role="group" aria-label="选择虚构人物">${peopleProfiles.map((v,i)=>`<button data-profile="${i}" class="${i===profileIndex?'active':''}" aria-pressed="${i===profileIndex}">${v.name}</button>`).join('')}</div></div><div class="people-layout">${profileHTML(p)}<div class="exercise">${peopleMode==='learn'?`<div class="phrase-list">${questions.map((item,i)=>`<section><h3>${item.label}</h3><p lang="es">${item.question}</p>${item.alternative?`<p lang="es" class="alternative">也可以问：${item.alternative}</p>`:''}<p class="phrase-answer" lang="es">${item.answers[0]}</p><button class="secondary" data-learn-q="${i}">♫ 听问题</button> <button class="secondary" data-learn-a="${i}">♫ 听回答</button></section>`).join('')}</div>`:`<span class="eyebrow">${peopleQuestionIndex+1} / ${questions.length} · ${q.label}</span><h2 lang="es">${q.question}</h2><p>${third?'用第三人称回答，例如 Se llama…、Tiene…、Es…':'以卡片人物的身份回答，例如 Me llamo…、Tengo…、Soy…'}</p><button id="people-question-audio" class="secondary">♫ 听问题</button><div class="exercise-block"><h3><span class="step">1</span>说出完整回答</h3><button id="people-record" class="secondary" ${!SR?'disabled':''}>♩ 点击开始说</button><p id="people-speech-feedback" class="feedback neutral" role="status">${SR?'允许麦克风后，用西班牙语回答。':'当前浏览器不支持语音识别，可以继续写句子。'}</p></div><form id="people-form" class="exercise-block"><h3><label for="people-answer"><span class="step">2</span>写出完整回答</label></h3><input id="people-answer" autocomplete="off" autocapitalize="none" spellcheck="false" aria-describedby="people-feedback" placeholder="输入完整的西班牙语句子…"><div class="accents">${['á','é','í','ó','ú','ñ'].map(c=>`<button type="button" data-people-char="${c}">${c}</button>`).join('')}</div><button class="secondary" type="submit">检查回答</button><p id="people-feedback" class="feedback" role="status"></p></form><div class="quiz-bottom"><button class="secondary" id="people-reveal">听读答案</button><button class="primary" id="people-next">下一题 →</button></div>`}</div></div><div id="audio-status" class="status" role="status"></div></section><p class="hint">从自己到别人：te llamas → se llama；tienes → tiene；eres → es；vives → vive。年龄用 tener（Tengo doce años），不用 ser。浏览器识别结果仅供练习参考，不是专业发音评分；语音服务可能处理音频，本站不保存录音或答案。</p>`;
 document.querySelectorAll('[data-people-mode]').forEach(b=>b.onclick=()=>{peopleMode=b.dataset.peopleMode;peopleQuestionIndex=0;render()});
 document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{profileIndex=+b.dataset.profile;peopleQuestionIndex=0;render()});
 document.querySelectorAll('[data-learn-q]').forEach(b=>b.onclick=()=>speak(questions[+b.dataset.learnQ].question));
 document.querySelectorAll('[data-learn-a]').forEach(b=>b.onclick=()=>speak(questions[+b.dataset.learnA].answers[0]));
 if(peopleMode==='learn')return;
 document.getElementById('people-question-audio').onclick=()=>speak(q.question);
 document.getElementById('people-form').onsubmit=e=>{e.preventDefault();const value=document.getElementById('people-answer').value;if(!value.trim()){feedback('people-feedback','先写下完整回答吧。',null);return}const ok=peopleAnswerMatches(value,q);feedback('people-feedback',ok?'✓ 回答正确！':'本题还没有匹配。参考回答：'+q.answers[0],ok)};
 document.querySelectorAll('[data-people-char]').forEach(b=>b.onclick=()=>{const input=document.getElementById('people-answer');input.setRangeText(b.dataset.peopleChar,input.selectionStart,input.selectionEnd,'end');input.focus()});
 document.getElementById('people-reveal').onclick=()=>{feedback('people-feedback',q.answers[0],null);speak(q.answers[0])};
 document.getElementById('people-next').onclick=()=>{peopleQuestionIndex=(peopleQuestionIndex+1)%questions.length;render()};
 document.getElementById('people-record').onclick=()=>recordPeople(q);
}
function recordPeople(q){if(!SR)return;if(recognition){recognition.stop();return}stopPlayback();const current=generation,button=document.getElementById('people-record');const rec=new SR();recognition=rec;rec.lang='es-ES';rec.maxAlternatives=5;rec.interimResults=false;let received=false;button.classList.add('recording');button.textContent='■ 正在听，点击结束';feedback('people-speech-feedback','请说出完整回答…',null);
 rec.onresult=e=>{if(current!==generation)return;received=true;const results=Array.from(e.results[0]);const ok=results.some(r=>peopleAnswerMatches(r.transcript,q));feedback('people-speech-feedback',(ok?'✓ 识别匹配！':'识别未匹配，请听读答案后再试。')+' 听到「'+results[0].transcript+'」。',ok)};
 rec.onerror=e=>{if(current!==generation)return;received=true;feedback('people-speech-feedback',e.error==='not-allowed'?'请允许使用麦克风后重试。':e.error==='no-speech'?'没有听到声音，再试一次。':'语音识别暂时不可用，请检查麦克风或网络，也可以继续写句子。',false)};
 rec.onend=()=>{if(current!==generation)return;recognition=null;button.classList.remove('recording');button.textContent='♩ 再说一次';if(!received)feedback('people-speech-feedback','没有识别到答案，再试一次吧。',null)};
 try{rec.start()}catch{recognition=null;button.classList.remove('recording');button.textContent='♩ 点击重试';feedback('people-speech-feedback','无法启动录音，请检查麦克风权限。',false)}
}
